use clap::error::ErrorKind;
use clap::{Args, CommandFactory, Parser, Subcommand};
use snapbox::assert_data_eq;
use snapbox::str;

use crate::utils;

#[derive(Parser, Debug, PartialEq)]
#[command(name = "tool")]
struct Cli {
    #[command(flatten)]
    shared: Shared,
    #[command(subcommand)]
    command: Commands,
}

#[derive(Args, Debug, PartialEq)]
struct Shared {
    #[arg(long, global = true, default_value = "builtin.toml")]
    config: String,
    #[arg(long, global = true, value_name = "key=value")]
    define: Vec<String>,
}

#[derive(Subcommand, Debug, PartialEq)]
enum Commands {
    Serve(Serve),
    Check(Check),
}

#[derive(Args, Debug, PartialEq)]
struct Serve {
    #[arg(long, value_parser = clap::value_parser!(u16).range(1..))]
    port: u16,
    #[arg(long, conflicts_with = "https")]
    http: bool,
    #[arg(long)]
    https: bool,
    #[arg(last = true)]
    args: Vec<String>,
}

#[derive(Args, Debug, PartialEq)]
struct Check {
    path: Option<String>,
    #[arg(long)]
    strict: bool,
}

fn serve(port: u16, http: bool, https: bool, args: &[&str]) -> Cli {
    Cli {
        shared: Shared {
            config: "builtin.toml".to_owned(),
            define: Vec::new(),
        },
        command: Commands::Serve(Serve {
            port,
            http,
            https,
            args: args.iter().map(|s| s.to_owned()).collect(),
        }),
    }
}

#[test]
fn shared_args_before_subcommand() {
    let cli = Cli::try_parse_from([
        "tool",
        "--config",
        "app.toml",
        "--define",
        "a=1",
        "--define",
        "b=2",
        "serve",
        "--port",
        "8080",
    ])
    .unwrap();
    assert_eq!(
        cli,
        Cli {
            shared: Shared {
                config: "app.toml".to_owned(),
                define: vec!["a=1".to_owned(), "b=2".to_owned()],
            },
            command: Commands::Serve(Serve {
                port: 8080,
                http: false,
                https: false,
                args: Vec::new(),
            }),
        }
    );
}

#[test]
fn shared_args_after_subcommand() {
    let cli = Cli::try_parse_from([
        "tool",
        "serve",
        "--port",
        "8080",
        "--config",
        "app.toml",
        "--define",
        "a=1",
        "--define",
        "b=2",
    ])
    .unwrap();
    assert_eq!(
        cli,
        Cli {
            shared: Shared {
